int runApplication(voicelink::TtsPort& tts, voicelink::WifiPort& wifi,
                   voicelink::TextInputPort& input) {
  voicelink::Controller controller(tts, wifi);
  controller.start();
  std::string recognized;
  for (;;) {
    const auto state = controller.context().state;
    if (state == voicelink::State::Completed || state == voicelink::State::Idle)
      return 0;
    if (state == voicelink::State::Error) return 2;

    const auto status = input.next(controller.context().grammar, recognized);
    if (status == voicelink::IoStatus::Ok) {
      if (!recognized.empty()) controller.ingest(recognized);
    } else if (!controller.handleInputStatus(status)) {
      return controller.context().state == voicelink::State::Error ? 2 : 3;
    }
  }
}

