void secureWipe(std::vector<char>& value) {
  volatile char* bytes = value.empty() ? nullptr : value.data();
  for (std::size_t i = 0; i < value.size(); ++i) bytes[i] = 0;
  value.clear();
  value.shrink_to_fit();
}

