namespace voicelink {

bool BoardHookTts::speak(const std::string& text) {
  return voicelink_board_tts_speak(text.c_str()) == 0;
}

void BoardHookTts::stop() { (void)voicelink_board_tts_stop(); }

ScanResult BoardHookWifi::scan() {
  ScanResult result;
  voicelink_ap aps[16]{};
  size_t count = 0;
  const int status = voicelink_board_wifi_scan(aps, 16, &count);
  if (status < 0) {
    // -ENOSYS or any board error: FatalError, NOT an empty scan.
    result.status = IoStatus::FatalError;
    result.error_code = status;
    return result;
  }
  if (count > 16) count = 16;
  result.status = IoStatus::Ok;
  result.access_points.reserve(count);
  for (size_t i = 0; i < count; ++i) {
    aps[i].ssid[sizeof(aps[i].ssid) - 1] = '\0';
    result.access_points.push_back({aps[i].ssid, aps[i].rssi, aps[i].secured != 0});
  }
  return result;
}

ConnectResult BoardHookWifi::connect(const std::string& ssid, const char* password,
                                     std::size_t password_len) {
  ConnectResult result;
  const int status = voicelink_board_wifi_connect(
      ssid.c_str(), password, password_len);
  if (status == VOICELINK_WIFI_OK) {
    result.status = ConnectStatus::Ok;
    return result;
  }
  result.error_code = status;
  if (status == VOICELINK_WIFI_WRONG_PASSWORD)
    result.status = ConnectStatus::WrongPassword;
  else if (status == VOICELINK_WIFI_TIMEOUT)
    result.status = ConnectStatus::Timeout;
  else if (status == VOICELINK_WIFI_NOT_FOUND)
    result.status = ConnectStatus::NetworkNotFound;
  else
    result.status = ConnectStatus::Failed;
  return result;
}

IoStatus BoardHookAsr::next(Grammar grammar, std::string& text) {
  char buffer[256]{};
  const int status = voicelink_board_asr_next(
      static_cast<enum voicelink_grammar>(grammar), buffer, sizeof(buffer));
  if (status < 0) return IoStatus::FatalError;
  if (status == VOICELINK_SPEECH_TIMEOUT) return IoStatus::Timeout;
  if (status == VOICELINK_SPEECH_RETRY) return IoStatus::RetryableError;
  if (status != 0) return IoStatus::FatalError;
  buffer[sizeof(buffer) - 1] = '\0';
  text.assign(buffer);
  if (text.empty()) return IoStatus::Timeout;
  return IoStatus::Ok;
}

